<section class="admin-welcome"><div><p class="eyebrow">ÉVALUATIONS</p><h1><?= htmlspecialchars($course['title']) ?></h1><p>Compositions de section et examen final du cours.</p></div><div><a class="btn primary" href="/academie/formation?course=<?= $course['id'] ?>" target="_blank">▶ Prévisualiser le cours</a> <a class="btn secondary" href="/admin/cours/programme?course=<?= $course['id'] ?>">← Programme</a></div></section><div class="exam-admin-list"><?php if(!$assessments): ?><div class="panel admin-empty">Aucune évaluation. Créez-la depuis le constructeur du programme.</div><?php endif ?><?php foreach($assessments as $assessment): ?><section class="panel exam-admin-card"><header><div><span class="status published"><?= $assessment['type']==='final_exam'?'EXAMEN FINAL':'COMPOSITION' ?></span><h2><?= htmlspecialchars($assessment['title']) ?></h2><p><?= $assessment['module_title']?htmlspecialchars($assessment['module_title']):'Évaluation globale' ?> · <?= $assessment['question_count'] ?> question(s) · seuil <?= $assessment['passing_score'] ?>%</p></div><a class="btn primary" target="_blank" href="/academie/composition?id=<?= $assessment['id'] ?>">Voir le QCM →</a></header><details><summary>+ Ajouter une question</summary><form method="post" action="/admin/cours/programme" class="exam-question-form"><input type="hidden" name="builder_action" value="question"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><input type="hidden" name="assessment_id" value="<?= $assessment['id'] ?>"><label class="full">Question<input name="question" required></label><label>Réponse A<input name="option_a" required></label><label>Réponse B<input name="option_b" required></label><label>Réponse C<input name="option_c"></label><label>Réponse D<input name="option_d"></label><label class="full">Bonne réponse<input name="correct_answer" required placeholder="Recopiez exactement la bonne réponse"></label><label class="full">Explication après correction<textarea name="explanation" rows="3"></textarea></label><button class="btn primary full">Ajouter la question</button></form></details></section><?php endforeach ?></div><style>.exam-admin-list{display:flex;flex-direction:column;gap:15px}.exam-admin-card{padding:20px}.exam-admin-card header{display:flex;align-items:center;justify-content:space-between;gap:20px}.exam-admin-card h2{font-size:16px;margin:8px 0}.exam-admin-card p{color:var(--muted)}.exam-admin-card details{border-top:1px solid var(--line);margin-top:18px;padding-top:15px}.exam-admin-card summary{cursor:pointer;color:var(--primary);font-weight:700}.exam-question-form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.exam-question-form label{display:flex;flex-direction:column;gap:6px;font-size:10px;font-weight:700}.exam-question-form input,.exam-question-form textarea{border:1px solid var(--line);border-radius:7px;padding:10px}.exam-question-form .full{grid-column:1/-1}@media(max-width:700px){.exam-admin-card header{flex-direction:column;align-items:flex-start}.exam-question-form{grid-template-columns:1fr}.exam-question-form .full{grid-column:1}}</style>
